function UFOOrb() {
  const cx = 280, cy = 208

  const oRx = 240, oRy = 29
  const bCy = 200, bRx = 152, bRy = 18
  const iRx = 92, iRy = 15, iCy = 213
  const dRx = 78, dRy = 12, dCy = 195, dApexY = 108
  const pCy = 250, pRx = 26, pRy = 9

  const rL = cx - oRx, rR = cx + oRx
  const bL = cx - bRx, bR = cx + bRx
  const iL = cx - iRx, iR = cx + iRx
  const dL = cx - dRx, dR = cx + dRx

  const hatches = Array.from({ length: 9 }, (_, i) => {
    const t = (i + 1) / 10
    const y = dApexY + t * (dCy - dApexY)
    const w = dRx * Math.sqrt(t) * 0.9
    return { y, w }
  })

  const radials = Array.from({ length: 14 }, (_, i) => {
    const angle = (i / 14) * Math.PI * 2
    const cos = Math.cos(angle)
    const sin = Math.sin(angle)

    return {
      x1: cx + pRx * 1.15 * cos,
      y1: pCy + pRy * Math.abs(sin) * 0.5,
      x2: cx + iRx * cos,
      y2: iCy + iRy * Math.abs(sin) * 0.4,
    }
  })

  const discTopHatches = Array.from({ length: 9 }, (_, i) => {
    const t = (i + 1) / 10
    const x = rL + t * (rR - rL)
    const sinTerm = Math.sqrt(
      Math.max(0, 1 - Math.pow((x - cx) / oRx, 2))
    )
    const yTop = cy - oRy * sinTerm

    return { x, yTop }
  })

  const bandStripes = Array.from({ length: 22 }, (_, i) => {
    const t = (i + 0.5) / 22
    const angle = Math.PI * (1 - t)
    const bx = cx + bRx * Math.cos(angle)
    const by = bCy + bRy * Math.sin(angle) * 0.28

    return { bx, by }
  })

  const rimPanels = Array.from({ length: 8 }, (_, i) => {
    const a0 = Math.PI * (i / 8)
    const a1 = Math.PI * ((i + 0.5) / 8)

    return {
      x0: cx + oRx * Math.cos(Math.PI - a0),
      y0: cy - oRy * Math.sin(a0),
      x1: cx + oRx * Math.cos(Math.PI - a1),
      y1: cy - oRy * Math.sin(a1),
      bright: i % 2 === 0,
    }
  })

  return (
    <svg
      viewBox="0 0 560 370"
      width={540}
      height={356}
      style={{ overflow: 'visible' }}
      aria-hidden="true"
    >
      <defs>
        <radialGradient id="g-dome" cx="40%" cy="28%" r="65%">
          <stop offset="0%" stopColor="#ffffff" />
          <stop offset="50%" stopColor="#e9e9e9" />
          <stop offset="100%" stopColor="#bdbdbd" />
        </radialGradient>

        <linearGradient
          id="g-disc-top"
          x1="0.5"
          y1="0"
          x2="0.5"
          y2="1"
        >
          <stop offset="0%" stopColor="#f7f7f7" />
          <stop offset="100%" stopColor="#cfcfcf" />
        </linearGradient>

        <linearGradient
          id="g-band"
          x1="0.5"
          y1="0"
          x2="0.5"
          y2="1"
        >
          <stop offset="0%" stopColor="#f2f2f2" />
          <stop offset="25%" stopColor="#ffffff" />
          <stop offset="50%" stopColor="#b0b0b0" />
          <stop offset="75%" stopColor="#666666" />
          <stop offset="100%" stopColor="#d5d5d5" />
        </linearGradient>

        <radialGradient id="g-under" cx="50%" cy="30%" r="65%">
          <stop offset="0%" stopColor="#d8d8d8" />
          <stop offset="60%" stopColor="#a8a8a8" />
          <stop offset="100%" stopColor="#6f6f6f" />
        </radialGradient>

        <radialGradient id="g-bowl" cx="50%" cy="75%" r="58%">
          <stop offset="0%" stopColor="#b8b8b8" />
          <stop offset="100%" stopColor="#565656" />
        </radialGradient>

        <radialGradient id="g-port" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#ffffff" />
          <stop offset="38%" stopColor="rgba(180,180,180,0.9)" />
          <stop offset="75%" stopColor="rgba(80,80,80,0.25)" />
          <stop offset="100%" stopColor="rgba(0,0,0,0)" />
        </radialGradient>

        <radialGradient id="g-rim-tip" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="rgba(60,60,60,0.45)" />
          <stop offset="100%" stopColor="rgba(60,60,60,0)" />
        </radialGradient>

        <filter
          id="f-ambient"
          x="-40%"
          y="-40%"
          width="180%"
          height="180%"
        >
          <feGaussianBlur stdDeviation="12" />
        </filter>

        <filter
          id="f-port-glow"
          x="-80%"
          y="-80%"
          width="260%"
          height="260%"
        >
          <feGaussianBlur stdDeviation="9" />
        </filter>

        <filter
          id="f-rim-tip"
          x="-60%"
          y="-60%"
          width="220%"
          height="220%"
        >
          <feGaussianBlur stdDeviation="3" />
        </filter>
      </defs>

      {/* Ambient shadow */}
      <ellipse
        cx={cx}
        cy={272}
        rx={118}
        ry={26}
        fill="rgba(0,0,0,0.10)"
        filter="url(#f-ambient)"
      />

      {/* Underside ring */}
      <path
        d={`
          M ${rL} ${cy}
          A ${oRx} ${oRy} 0 0 0 ${rR} ${cy}
          L ${iR} ${iCy}
          A ${iRx} ${iRy} 0 0 1 ${iL} ${iCy}
          Z
        `}
        fill="url(#g-under)"
      />

      {/* Concave bowl */}
      <path
        d={`
          M ${iL} ${iCy}
          A ${iRx} ${iRy} 0 0 0 ${iR} ${iCy}
          Q ${cx + 66} ${pCy + 6} ${cx + pRx} ${pCy}
          A ${pRx} ${pRy} 0 0 1 ${cx - pRx} ${pCy}
          Q ${cx - 66} ${pCy + 6} ${iL} ${iCy}
          Z
        `}
        fill="url(#g-bowl)"
      />

      {/* Underside radiating lines */}
      {radials.map((r, i) => (
        <line
          key={i}
          x1={r.x1}
          y1={r.y1}
          x2={r.x2}
          y2={r.y2}
          stroke="rgba(0,0,0,0.14)"
          strokeWidth={0.75}
        />
      ))}

      {/* Underside concentric arcs */}
      {[0.36, 0.62, 0.86].map((s, i) => (
        <path
          key={i}
          d={`M ${cx - iRx * s} ${iCy + 3} A ${iRx * s} ${
            iRy * s * 0.45
          } 0 0 0 ${cx + iRx * s} ${iCy + 3}`}
          fill="none"
          stroke={`rgba(0,0,0,${0.08 + i * 0.03})`}
          strokeWidth={0.8}
        />
      ))}

      {/* Inner hull */}
      <path
        d={`M ${iL} ${iCy} A ${iRx} ${iRy} 0 0 0 ${iR} ${iCy}`}
        fill="none"
        stroke="rgba(0,0,0,0.28)"
        strokeWidth={0.9}
      />

      <path
        d={`M ${iL} ${iCy} A ${iRx} ${iRy} 0 0 1 ${iR} ${iCy}`}
        fill="none"
        stroke="rgba(0,0,0,0.12)"
        strokeWidth={0.6}
      />

      {/* Center port */}
      <ellipse
        cx={cx}
        cy={pCy}
        rx={52}
        ry={24}
        fill="url(#g-port)"
        filter="url(#f-port-glow)"
        opacity={0.55}
      />

      <ellipse
        cx={cx}
        cy={pCy}
        rx={pRx + 3}
        ry={pRy + 2}
        fill="#ffffff"
        stroke="#222222"
        strokeWidth={1}
      />

      <ellipse
        cx={cx}
        cy={pCy}
        rx={pRx}
        ry={pRy}
        fill="url(#g-port)"
      />

      {/* Disc top */}
      <path
        d={`
          M ${rL} ${cy}
          A ${oRx} ${oRy} 0 0 1 ${rR} ${cy}
          L ${bR} ${bCy}
          A ${bRx} ${bRy} 0 0 1 ${bL} ${bCy}
          Z
        `}
        fill="url(#g-disc-top)"
      />

      {/* Disc hatches */}
      {discTopHatches.map((h, i) => (
        <line
          key={i}
          x1={h.x}
          y1={h.yTop}
          x2={h.x}
          y2={bCy + 2}
          stroke="rgba(0,0,0,0.08)"
          strokeWidth={0.65}
        />
      ))}

      {/* Rim panels */}
      {rimPanels.map((p, i) => (
        <line
          key={i}
          x1={p.x0}
          y1={p.y0}
          x2={p.x1}
          y2={p.y1}
          stroke={
            p.bright
              ? 'rgba(0,0,0,0.28)'
              : 'rgba(0,0,0,0.10)'
          }
          strokeWidth={p.bright ? 2.5 : 1}
        />
      ))}

      {/* Equatorial band */}
      <path
        d={`
          M ${bL} ${bCy}
          A ${bRx} ${bRy} 0 0 1 ${bR} ${bCy}
          A ${bRx} ${bRy} 0 0 1 ${bL} ${bCy}
          Z
        `}
        fill="url(#g-band)"
      />

      <path
        d={`M ${bL} ${bCy} A ${bRx} ${bRy} 0 0 1 ${bR} ${bCy}`}
        fill="none"
        stroke="rgba(0,0,0,0.22)"
        strokeWidth={0.8}
      />

      {bandStripes.map((s, i) => (
        <line
          key={i}
          x1={s.bx}
          y1={s.by - 5}
          x2={s.bx}
          y2={s.by + 8}
          stroke="rgba(0,0,0,0.16)"
          strokeWidth={0.7}
        />
      ))}

      {/* Dome */}
      <path
        d={`
          M ${dL} ${dCy}
          Q ${dL - 5} ${(dApexY + dCy) / 2 + 8} ${cx} ${dApexY}
          Q ${dR + 5} ${(dApexY + dCy) / 2 + 8} ${dR} ${dCy}
          A ${dRx} ${dRy} 0 0 1 ${dL} ${dCy}
          Z
        `}
        fill="url(#g-dome)"
      />

      {/* Dome hatches */}
      {hatches.map((h, i) => (
        <line
          key={i}
          x1={cx - h.w}
          y1={h.y}
          x2={cx + h.w}
          y2={h.y}
          stroke="rgba(0,0,0,0.10)"
          strokeWidth={0.75}
        />
      ))}

      {/* Dome reflection */}
      <path
        d={`
          M ${cx - 20} ${dApexY + 16}
          Q ${cx - 58} ${(dApexY + dCy) / 2 + 4} ${
            cx - 62
          } ${dCy - 7}
          Q ${cx - 36} ${(dApexY + dCy) / 2 - 5} ${
            cx - 9
          } ${dApexY + 20}
          Z
        `}
        fill="rgba(255,255,255,0.35)"
        opacity={0.85}
      />

      {/* Dome outline */}
      <path
        d={`
          M ${dL} ${dCy}
          Q ${dL - 5} ${(dApexY + dCy) / 2 + 8} ${cx} ${dApexY}
          Q ${dR + 5} ${(dApexY + dCy) / 2 + 8} ${dR} ${dCy}
        `}
        fill="none"
        stroke="rgba(0,0,0,0.45)"
        strokeWidth={1}
      />

      <ellipse
        cx={cx}
        cy={dCy}
        rx={dRx}
        ry={dRy}
        fill="none"
        stroke="rgba(0,0,0,0.22)"
        strokeWidth={0.9}
      />

      {/* Outer rim */}
      <path
        d={`M ${rL} ${cy} A ${oRx} ${oRy} 0 0 1 ${rR} ${cy}`}
        fill="none"
        stroke="rgba(0,0,0,0.45)"
        strokeWidth={1.2}
      />

      <path
        d={`M ${rL} ${cy} A ${oRx} ${oRy} 0 0 0 ${rR} ${cy}`}
        fill="none"
        stroke="rgba(0,0,0,0.18)"
        strokeWidth={0.8}
      />

      {/* Rim glows */}
      <ellipse
        cx={rL + 6}
        cy={cy}
        rx={9}
        ry={7}
        fill="url(#g-rim-tip)"
        filter="url(#f-rim-tip)"
      />

      <ellipse
        cx={rR - 6}
        cy={cy}
        rx={9}
        ry={7}
        fill="url(#g-rim-tip)"
        filter="url(#f-rim-tip)"
      />

      {/* HUD labels */}
      <text
        x={rL + 16}
        y={cy - 40}
        fontFamily="DM Mono, monospace"
        fontSize={8}
        fill="rgba(0,0,0,0.42)"
        letterSpacing="0.1em"
      >
        TRCK-09
      </text>

      <text
        x={rR - 116}
        y={cy - 40}
        fontFamily="DM Mono, monospace"
        fontSize={8}
        fill="rgba(0,0,0,0.42)"
        letterSpacing="0.1em"
      >
        51°32'N · 07°28'E
      </text>

      <text
        x={cx - 38}
        y={pCy + 30}
        fontFamily="DM Mono, monospace"
        fontSize={8}
        fill="rgba(0,0,0,0.42)"
        letterSpacing="0.1em"
      >
        ALT 00.00 KM
      </text>
    </svg>
  )
}

export default UFOOrb